56	public class RaptorConnector
57	        implements Connector
58	{
59	    private static final Logger log = Logger.get(RaptorConnector.class);
60	
61	    private final LifeCycleManager lifeCycleManager;
62	    private final RaptorMetadataFactory metadataFactory;
63	    private final RaptorSplitManager splitManager;
64	    private final RaptorPageSourceProvider pageSourceProvider;
65	    private final RaptorPageSinkProvider pageSinkProvider;
66	    private final RaptorNodePartitioningProvider nodePartitioningProvider;
67	    private final List<PropertyMetadata<?>> sessionProperties;
68	    private final List<PropertyMetadata<?>> tableProperties;
69	    private final Set<SystemTable> systemTables;
70	    private final MetadataDao dao;
71	    private final boolean coordinator;
72	
73	    private final ConcurrentMap<ConnectorTransactionHandle, RaptorMetadata> transactions = new ConcurrentHashMap<>();
74	
75	    private final ScheduledExecutorService unblockMaintenanceExecutor = newSingleThreadScheduledExecutor(daemonThreadsNamed("raptor-unblock-maintenance"));
76	
77	    @GuardedBy("this")
78	    private final SetMultimap<Long, UUID> deletions = HashMultimap.create();
79	
80	    @Inject
81	    public RaptorConnector(
82	            LifeCycleManager lifeCycleManager,
83	            NodeManager nodeManager,
84	            RaptorMetadataFactory metadataFactory,
85	            RaptorSplitManager splitManager,
86	            RaptorPageSourceProvider pageSourceProvider,
87	            RaptorPageSinkProvider pageSinkProvider,
88	            RaptorNodePartitioningProvider nodePartitioningProvider,
89	            RaptorSessionProperties sessionProperties,
90	            RaptorTableProperties tableProperties,
91	            Set<SystemTable> systemTables,
92	            @ForMetadata IDBI dbi)
93	    {
94	        this.lifeCycleManager = requireNonNull(lifeCycleManager, "lifeCycleManager is null");
95	        this.metadataFactory = requireNonNull(metadataFactory, "metadataFactory is null");
96	        this.splitManager = requireNonNull(splitManager, "splitManager is null");
97	        this.pageSourceProvider = requireNonNull(pageSourceProvider, "pageSourceProvider is null");
98	        this.pageSinkProvider = requireNonNull(pageSinkProvider, "pageSinkProvider is null");
99	        this.nodePartitioningProvider = requireNonNull(nodePartitioningProvider, "nodePartitioningProvider is null");
100	        this.sessionProperties = requireNonNull(sessionProperties, "sessionProperties is null").getSessionProperties();
101	        this.tableProperties = requireNonNull(tableProperties, "tableProperties is null").getTableProperties();
102	        this.systemTables = requireNonNull(systemTables, "systemTables is null");
103	        this.dao = onDemandDao(dbi, MetadataDao.class);
104	        this.coordinator = nodeManager.getCurrentNode().isCoordinator();
105	    }
106	
107	    @PostConstruct
108	    public void start()
109	    {
110	        if (coordinator) {
111	            dao.unblockAllMaintenance();
112	        }
113	    }
114	
115	    @Override
116	    public boolean isSingleStatementWritesOnly()
117	    {
118	        return true;
119	    }
120	
121	    @Override
122	    public ConnectorTransactionHandle beginTransaction(IsolationLevel isolationLevel, boolean readOnly)
123	    {
124	        checkConnectorSupports(READ_COMMITTED, isolationLevel);
125	        RaptorTransactionHandle transaction = new RaptorTransactionHandle();
126	        transactions.put(transaction, metadataFactory.create(tableId -> beginDelete(tableId, transaction.getUuid())));
127	        return transaction;
128	    }
129	
130	    @Override
131	    public void commit(ConnectorTransactionHandle transaction)
132	    {
133	        checkArgument(transactions.remove(transaction) != null, "no such transaction: %s", transaction);
134	        finishDelete(((RaptorTransactionHandle) transaction).getUuid());
135	    }
136	
137	    @Override
138	    public void rollback(ConnectorTransactionHandle transaction)
139	    {
140	        RaptorMetadata metadata = transactions.remove(transaction);
141	        checkArgument(metadata != null, "no such transaction: %s", transaction);
142	        finishDelete(((RaptorTransactionHandle) transaction).getUuid());
143	        metadata.rollback();
144	    }
145	
146	    @Override
147	    public ConnectorPageSourceProvider getPageSourceProvider()
148	    {
149	        return pageSourceProvider;
150	    }
151	
152	    @Override
153	    public ConnectorPageSinkProvider getPageSinkProvider()
154	    {
155	        return pageSinkProvider;
156	    }
157	
158	    @Override
159	    public ConnectorMetadata getMetadata(ConnectorTransactionHandle transaction)
160	    {
161	        RaptorMetadata metadata = transactions.get(transaction);
162	        checkArgument(metadata != null, "no such transaction: %s", transaction);
163	        return metadata;
164	    }
165	
166	    @Override
167	    public ConnectorSplitManager getSplitManager()
168	    {
169	        return splitManager;
170	    }
