28	import com.google.inject.Injector;
29	import com.google.inject.Module;
30	import io.airlift.bootstrap.Bootstrap;
31	import io.airlift.json.JsonModule;
32	import org.weakref.jmx.guice.MBeanModule;
33	
34	import javax.management.MBeanServer;
35	
36	import java.util.Map;
37	
38	import static com.google.common.base.Preconditions.checkArgument;
39	import static com.google.common.base.Strings.isNullOrEmpty;
40	import static java.lang.management.ManagementFactory.getPlatformMBeanServer;
41	import static java.util.Objects.requireNonNull;
42	
43	public class RaptorConnectorFactory
44	        implements ConnectorFactory
45	{
46	    private final String name;
47	    private final Module metadataModule;
48	    private final Map<String, Module> backupProviders;
49	
50	    public RaptorConnectorFactory(String name, Module metadataModule, Map<String, Module> backupProviders)
51	    {
52	        checkArgument(!isNullOrEmpty(name), "name is null or empty");
53	        this.name = name;
54	        this.metadataModule = requireNonNull(metadataModule, "metadataModule is null");
55	        this.backupProviders = ImmutableMap.copyOf(requireNonNull(backupProviders, "backupProviders is null"));
56	    }
57	
58	    @Override
59	    public String getName()
60	    {
61	        return name;
62	    }
63	
64	    @Override
65	    public ConnectorHandleResolver getHandleResolver()
66	    {
67	        return new RaptorHandleResolver();
68	    }
69	
70	    @Override
71	    public Connector create(String connectorId, Map<String, String> config, ConnectorContext context)
72	    {
73	        NodeManager nodeManager = context.getNodeManager();
74	        try {
75	            Bootstrap app = new Bootstrap(
76	                    new JsonModule(),
77	                    new MBeanModule(),
78	                    binder -> {
79	                        MBeanServer mbeanServer = new RebindSafeMBeanServer(getPlatformMBeanServer());
80	                        binder.bind(MBeanServer.class).toInstance(mbeanServer);
81	                        binder.bind(NodeManager.class).toInstance(nodeManager);
82	                        binder.bind(PageSorter.class).toInstance(context.getPageSorter());
83	                        binder.bind(TypeManager.class).toInstance(context.getTypeManager());
84	                    },
85	                    metadataModule,
86	                    new BackupModule(backupProviders),
87	                    new StorageModule(connectorId),
88	                    new RaptorModule(connectorId));
89	
90	            Injector injector = app
91	                    .strictConfig()
92	                    .doNotInitializeLogging()
93	                    .setRequiredConfigurationProperties(config)
94	                    .initialize();
95	
96	            return injector.getInstance(RaptorConnector.class);
97	        }
98	        catch (Exception e) {
99	            throw Throwables.propagate(e);
100	        }
101	    }
102	}
