package com.facebook.presto.raptor.security;

import com.google.common.collect.ImmutableSet;
import io.airlift.configuration.Config;

import javax.validation.constraints.NotNull;

import java.util.Set;

import static com.google.common.base.Preconditions.checkArgument;
import static java.util.Locale.ENGLISH;
import static java.util.Objects.requireNonNull;

public class RaptorSecurityConfig
{
    private static final Set<String> ALLOWED_SECURITY_SYSTEMS = ImmutableSet.of("none", "file", "read-only");

    private String securitySystem = "none";

    @NotNull
    public String getSecuritySystem()
    {
        return securitySystem;
    }

    @Config("raptor.security")
    public RaptorSecurityConfig setSecuritySystem(String securitySystem)
    {
        requireNonNull(securitySystem, "securitySystem is null");
        checkArgument(
                ALLOWED_SECURITY_SYSTEMS.contains(securitySystem.toLowerCase(ENGLISH)),
                "Unknown security system: %s",
                securitySystem);
        this.securitySystem = securitySystem;
        return this;
    }
}
